using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEditor;
using System.Text;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        var all = Resources.FindObjectsOfTypeAll<Transform>();
        foreach (var t in all)
        {
            if (t == null) continue;
            if (!t.name.Contains("Yellow") && !t.name.Contains("HUD") && t.name != "Multiplayer") continue;
            if (EditorUtility.IsPersistent(t.gameObject)) continue;
            string path = t.name;
            var p = t.parent;
            while (p != null) { path = p.name + "/" + path; p = p.parent; }
            sb.AppendLine(path + " activeSelf=" + t.gameObject.activeSelf + " id=" + t.gameObject.GetInstanceID());
        }

        // YellowHUD controller
        var yellow = Object.FindObjectsOfType<Railbound.UI.RailboundYellowHUDController>(true);
        sb.AppendLine("YellowHUD controllers=" + yellow.Length);
        foreach (var y in yellow)
        {
            sb.AppendLine("  on " + y.gameObject.name + " enabled=" + y.enabled + " goActive=" + y.gameObject.activeSelf);
            var so = new SerializedObject(y);
            var prop = so.GetIterator();
            bool enter = true;
            int nulls = 0, set = 0;
            while (prop.NextVisible(enter))
            {
                enter = false;
                if (prop.propertyType == SerializedPropertyType.ObjectReference)
                {
                    if (prop.objectReferenceValue == null) nulls++; else set++;
                }
            }
            sb.AppendLine("  refs set=" + set + " null=" + nulls);
        }

        var bridge = Object.FindObjectsOfType<Michsky.UI.Reach.ReachLobbyBridge>(true);
        sb.AppendLine("ReachLobbyBridge=" + bridge.Length);
        foreach (var b in bridge)
            sb.AppendLine("  on " + b.gameObject.name + " active=" + b.gameObject.activeInHierarchy);

        ctx.ReturnValue = sb.ToString();
    }
}
